  return workspace(v, '/whm/services/web', msgid('Web server'), msgid('A single reviewed web stack, per-account process identity and tested configuration changes.'), card(v, 'web-stack', msgid('Engine and workers'), settings), card(v, 'web-backend', msgid(msgctxt('approved-xwhm', 'Backend connection')), facts(v, [[msgid('Saved HTTP port'), s?.backendPort], [msgid('Saved TLS port'), s?.backendTlsPort]]) + `<p>${v.text(msgid('These are saved backend settings. Listener ownership and per-account request identity require actual runtime observations.'))}</p>` + renderWhmWebServerReadback(readback)) + card(v, 'web-pending', msgid(msgctxt('approved-xwhm', 'Pending change')), `${table(v, msgid('Pending configuration difference'), [msgid('Setting'), msgid('Current'), msgid('Proposed'), msgid('State')], [], msgid('No reviewed configuration difference has been read.'))}${actions(button(v, msgid('Discard pending change'), '', true))}<p>${v.text(msgid('Settings are read from the server before saving. The full current settings document is preserved, candidate syntax is checked, and the actual reconcile result is shown.'))}</p>`) + card(v, 'web-generations', msgid('Generations'), generationTable(v) + renderWhmWebGenerationControls(readback)))
