const setup = (v: View): string => {
  const s = v.props.serverSettings
  const workersView = { ...v, readOnly: v.readOnly || !s }
  const primaryIpv4 = v.props.ipPool?.find(ip => ip.isPrimary && ip.version === 4)?.address
  const identity = `<ol class="xp-whm-detail-steps" aria-label="${v.text(msgid('Setup steps'))}">${[msgid('Host and nameservers'), msgid('Engine and workers'), msgid('Review'), msgid('Apply')].map((step, i) => `<li><strong>${i + 1}</strong><span>${v.text(step)}</span></li>`).join('')}</ol>${form(v, 'setup-wizard-form', `<div class="xp-whm-detail-fields">${field(v, 'hostname', msgid('Server hostname'), { value: s?.hostname })}${field(v, 'adminEmail', msgid('Admin email'), { value: s?.adminEmail, type: 'email' })}${field(v, 'primaryIpv4', msgid('Primary IPv4 address'), { value: primaryIpv4, required: true, help: msgid('Use the actual primary IPv4 assigned to this server. No address is generated or assumed.') })}${field(v, 'engine', msgid('Web engine'), { value: s?.engine, choices: engineChoices })}${field(v, 'apacheMpm', 'Apache MPM', { value: s?.apacheMpm, choices: mpmChoices })}${field(v, 'panelPort', msgid('Panel port'), { value: s?.panelPort, type: 'number' })}${field(v, 'sshPort', msgid('SSH port'), { value: s?.sshPort, type: 'number' })}</div>${field(v, 'nameservers', msgid('Nameservers, one per line'), { value: s?.nameservers.join('\n'), type: 'textarea' })}${field(v, 'quotaFilesystem', msgid('Quota filesystem'), { help: msgid('A path alone does not establish that quotas are enabled.') })}${actions(save(v, msgid('Review setup')))}`)}`
  const nameservers = `<div class="xp-whm-detail-fields">${field(v, 'setup-nameserver-1', msgid('Nameserver 1'), { value: s?.nameservers[0], disabled: true })}${field(v, 'setup-nameserver-1-address', msgid('Nameserver 1 address'), { disabled: true })}${field(v, 'setup-nameserver-2', msgid('Nameserver 2'), { value: s?.nameservers[1], disabled: true })}${field(v, 'setup-nameserver-2-address', msgid('Nameserver 2 address'), { disabled: true })}</div>${status(v, msgid('Names are read from the saved nameserver list and can be changed in the list above. Nameserver addresses have not been read; address assignment has no connected setup operation.'))}`
  const notices = [
    ['setup-notice-config-failure', msgid('Failed configuration tests and rollbacks')],
    ['setup-notice-certificate', msgid('Certificates that fail to renew')],
    ['setup-notice-upgrade', msgid('Upgrade results')],
    ['setup-notice-signin', msgid('Paused sign-ins to xWHM')],
  ] as const
  const nginx = `<h3>${v.text(msgid('Nginx at the edge'))}</h3><div class="xp-whm-detail-fields">${field(workersView, 'nginx.workerProcesses', 'worker_processes', { value: s?.nginx.workerProcesses, id: 'whm-setup-nginx-workers' })}${field(workersView, 'nginx.workerConnections', 'worker_connections', { value: s?.nginx.workerConnections, type: 'number', id: 'whm-setup-nginx-connections' })}${field(workersView, 'nginx.workerRlimitNofile', 'worker_rlimit_nofile', { value: s?.nginx.workerRlimitNofile, type: 'number', id: 'whm-setup-nginx-nofile' })}${field(workersView, 'nginx.keepaliveTimeoutSec', msgid('keepalive_timeout (seconds)'), { value: s?.nginx.keepaliveTimeoutSec, type: 'number', id: 'whm-setup-nginx-keepalive', help: msgid('0 disables keepalive. The saved timeout is not a measurement of live connections.') })}</div>${choice(workersView, 'nginx.multiAccept', 'multi_accept', s?.nginx.multiAccept)}`
  const apache = `<h3>${v.text('Apache mpm-itk')}</h3><div class="xp-whm-detail-fields">${([['startServers', 'StartServers'], ['minSpareServers', 'MinSpareServers'], ['maxSpareServers', 'MaxSpareServers'], ['maxRequestWorkers', 'MaxRequestWorkers'], ['serverLimit', 'ServerLimit'], ['maxConnectionsPerChild', 'MaxConnectionsPerChild']] as const).map(([key, label]) => field(workersView, `apache.${key}`, label, { value: s?.apache[key], type: 'number', id: `whm-setup-apache-${key}` })).join('')}</div>${choice(v, 'setup-apache-unlimited', msgid('Unlimited child lifetime'), s ? s.apache.maxConnectionsPerChild === 0 : undefined, true)}<p class="xp-help">${v.text(msgid('Set MaxConnectionsPerChild to 0 for an unlimited child lifetime; the checkbox reflects the saved value.'))}</p>`
  const workers = `${!s ? status(v, msgid('Worker settings have not been read. Reload after the saved server settings are available; no suggested values are assumed.')) : ''}${form(workersView, 'server-settings-form', `${nginx}${apache}${actions(save(workersView, msgid('Save worker settings')))}`)}${actions(button(v, msgid('Reset to suggested values'), '', true))}${status(v, msgid('The worker form stores only the displayed settings through the existing server-settings operation. It does not establish that a candidate generation was tested or activated.'))}`
  const accountDefaults = `<h3>${v.text(msgid('Default PHP-FPM pool for new accounts'))}</h3><div class="xp-whm-detail-fields">${field(v, 'setup-fpm-mode', 'pm', { disabled: true, choices: [['ondemand', 'ondemand'], ['dynamic', 'dynamic'], ['static', 'static']] })}${field(v, 'setup-fpm-max-children', 'pm.max_children', { type: 'number', disabled: true })}${field(v, 'setup-fpm-idle-timeout', 'pm.process_idle_timeout', { type: 'number', disabled: true })}${field(v, 'setup-fpm-max-requests', 'pm.max_requests', { type: 'number', disabled: true })}</div><h3>${v.text(msgid('OpenLiteSpeed and lsphp'))}</h3><div class="xp-whm-detail-fields">${field(v, 'setup-lsphp-server-connections', msgid('Server max connections'), { type: 'number', disabled: true })}${field(v, 'setup-lsphp-account-children', msgid('lsphp children per account'), { type: 'number', disabled: true })}${field(v, 'setup-lsphp-account-connections', msgid('lsphp connections per account'), { type: 'number', disabled: true })}</div>${status(v, msgid('Global account defaults for PHP-FPM and lsphp have not been read and have no connected setup write operation. Per-domain PHP settings do not establish these global defaults.'))}`
  return workspace(v, '/whm/server/setup', msgid('Set up this server'), msgid('Review identity, web engine, worker limits and candidate tests before applying a generation.'),
    card(v, 'setup-wizard', msgid('Server identity and engine'), identity)
    + card(v, 'setup-nameservers', msgid('Host and nameservers'), nameservers)
    + card(v, 'setup-notices', msgid('Send notices about'), notices.map(([name, label]) => choice(v, name, label, undefined, true)).join('') + status(v, msgid('Notification preferences have not been read and cannot be saved by the setup API. No delivery or always-sent policy is assumed.')))
    + card(v, 'setup-workers', msgid('Workers and account defaults'), workers)
    + card(v, 'setup-account-defaults', msgid('New account PHP defaults'), accountDefaults)
    + card(v, 'setup-tests', msgid('Tests on the candidate generation'), table(v, msgid('Candidate generation tests'), [msgid('Check'), msgid('Result')], [], msgid('No candidate-generation test result has been returned for this setup request.')) + actions(button(v, msgid('Apply first generation'), '', true, true) + button(v, msgid('Back'), '', true) + button(v, msgid('Continue'), '', true))),
    card(v, 'setup-detected', msgid(msgctxt('approved-xwhm', 'Detected on this host')), facts(v, [[msgid('Hostname'), v.props.hostname], [msgid('Engine'), v.props.hostSample?.engine], [msgid('System'), v.props.hostSample?.system], [msgid('Kernel'), v.props.hostSample?.kernel]]) + `<p>${v.text(msgid('Repository plans and saved metadata do not prove that packages, quotas or isolation are active on this host.'))}</p>` + actions(button(v, msgid('Detect again'), '', true)))
    + card(v, 'setup-handler-map', msgid('PHP handlers by engine'), table(v, msgid('PHP handler compatibility'), [msgid('Engine'), msgid('Handlers'), msgid('Availability')], [['Apache + mpm-itk', 'PHP-FPM, CGI / suexec', v.text(unavailable)], ['OpenLiteSpeed', 'lsphp', v.text(unavailable)]])))
}

const transfer = (v: View): string => {
  const pending = { ...v, readOnly: true }
  const savedWorkspace = renderWhmTransferWorkspace({ lang: v.locale, canManage: v.root && !v.readOnly, readCredentials: true })
  const source = `<ol class="xp-whm-detail-steps">${[msgid('Connect'), msgid('Accounts'), msgid('Review'), msgid('Transfer')].map((step, i) => `<li><strong>${i + 1}</strong>${v.text(step)}</li>`).join('')}</ol>${actions(button(pending, msgid('Change source')))}${form(pending, 'whm-transfer-form', `<div class="xp-whm-detail-fields">${field(pending, 'sourceHost', msgid('Source host'))}${field(pending, 'sourcePort', msgid('SSH or API port'), { type: 'number' })}</div><h3>${v.text(msgid('Authentication'))}</h3><div class="xp-whm-detail-choice-grid">${[['ssh-key', msgid('SSH key')], ['api-token', msgid('API token')]].map(([raw, label]) => `<label class="xp-whm-detail-choice"><input type="radio" name="transfer-auth-mode" value="${raw}" disabled><span>${v.text(label as Copy)}</span></label>`).join('')}</div>${field(pending, 'transfer-key-file', msgid('Key on this server'))}${actions(button(pending, msgid('Copy public key')))}${field(pending, 'transfer-api-token', msgid('API token from the source'), { type: 'password' })}${field(pending, 'accountNames', msgid('Accounts to transfer'), { type: 'textarea' })}${actions(button(pending, msgid('Test connection')) + button(pending, msgid('Check transfer request'), 'data-action="start-transfer"', false, true))}`)}${status(v, msgid('The current lifecycle API records and reviews transfer state. It does not connect to a remote source or prove that account data has been copied. Connection, credentials and discovery remain unavailable here.')).replace('<p ', '<p data-transfer-source-observation ')}`
  const conflicts = `${table(v, msgid('Source accounts and conflicts'), [msgid('Selected'), msgid('Username'), msgid('Domain'), msgid('Plan'), msgid('Disk'), msgid('Databases'), msgid('Mailboxes'), msgid('Conflict'), msgid('Resolution')], [], undefined, true).replace('<tbody>', '<tbody data-transfer-inventory-rows>')}<div class="xp-whm-detail-fields">${field(pending, 'transfer-conflict-account', msgid('Account with a conflict'), { choices: [] })}${field(pending, 'transfer-conflict-resolution', msgid('Resolve conflict'), { choices: [['skip', msgid('Skip account')], ['rename', msgid('Rename before transfer')], ['replace-reviewed', msgid('Replace after reviewed backup')]] })}</div>${status(v, msgid('Source inventory and destination conflict checks have not been read. No account selection or replacement is assumed.')).replace('<p ', '<p data-transfer-identities-observation ')}`
  const progress = `<div data-transfer-progress-state="not-read">${status(v, msgid('No native transfer job or per-account progress has been read.'))}</div>${table(v, msgid('Transfer progress'), [msgid('Account'), msgid('Files'), msgid('Databases'), msgid('Mail'), 'DNS', msgid('State')], [], undefined, true).replace('<tbody>', '<tbody data-transfer-progress-rows>')}${actions(button(pending, msgid('Back')) + button(pending, msgid('Stop after the current account')) + button(pending, msgid('Start transfer'), '', false, true))}`
  const imported = `${field(pending, 'cpanel-backup', msgid('Backup file'), { type: 'file' })}${actions(button(pending, msgid('Preview import')))}<h3>${v.text(msgid('Parsed plan'))}</h3><div class="xp-whm-detail-fields">${field(pending, 'cpanel-plan', msgid('Plan here'), { choices: (v.props.plans ?? []).map(plan => [plan.name, plan.name] as const) })}${field(pending, 'cpanel-owner', msgid('Owner'), { choices: (v.props.resellers ?? []).map(reseller => [reseller.username, reseller.username] as const) })}</div>${[msgid('Domains'), msgid('Home files'), msgid('Databases and users'), msgid('Mailboxes and filters'), msgid('DNS records')].map((title, i) => `<details data-transfer-import-part="${['domains','home','databases','mail','dns'][i]}"><summary>${v.text(title)}</summary>${table(v, title, [msgid('Item'), msgid('Source'), msgid('Destination'), msgid('Action')], [], undefined, true)}</details>`).join('')}<h3>${v.text(msgid('Not imported or changed'))}</h3>${table(v, msgid('Import exclusions and warnings'), [msgid('Item'), msgid('Reason'), msgid('Path')], [], undefined, true).replace('<tbody>', '<tbody data-transfer-import-warnings>')}${status(v, msgid('The native cPanel archive import adapter is not connected. No archive was parsed or uploaded. Passwords, account identities, owners and paths must be reviewed from a real import plan before any mutation.')).replace('<p ', '<p data-transfer-import-observation ')}${actions(button(pending, msgid('Discard upload')) + button(pending, msgid('Import selected account'), '', false, true))}`
  return workspace(v, '/whm/transfers', msgid('Transfer tool'), msgid('Review source identity, discovered accounts, conflicts and the import plan before moving data.'), savedWorkspace + card(v, 'transfer-source', msgid('Transfer from an xPanel server'), source) + card(v, 'transfer-identities', msgid('Accounts on the source'), conflicts) + card(v, 'transfer-progress', msgid('Transfer progress'), progress) + card(v, 'transfer-import', msgid('Import a cPanel backup'), imported), card(v, 'transfer-plans', msgid('Plans used by the selected accounts'), table(v, msgid('Source plan review'), [msgid('Source plan'), msgid('Destination plan'), msgid('Owner'), msgid('Conflict')], [], undefined, true).replace('<tbody>', '<tbody data-transfer-plan-rows>') + status(v, msgid('Source plans have not been discovered. Names, limits and ownership must be reviewed before import.')).replace('<p ', '<p data-transfer-plan-observation ')))
}

