const dnsComponents = (v: View): string => {
  const pending = { ...v, readOnly: true }
  const provider = v.props.services?.find(service => /^(?:pdns|powerdns)$/i.test(service.name))
  const checkedProvider = provider?.checked !== false ? provider : undefined
  return card(v, 'dns-zone-list', msgid('Zones'), `<span class="xp-help" data-whm-dns-zone-count role="status">${v.text(unavailable)}</span>${table(v, msgid('DNS zones'), [msgid('Zone'), msgid('Account'), msgid('Records'), msgid('Serial'), msgid('Provider state')], []).replace('<tbody>', '<tbody data-whm-dns-zone-rows>')}${actions(button(pending, msgid('Previous')) + button(pending, msgid('Next')))}`) + card(v, 'dns-zone-file', msgid('Zone file'), `${actions(button(pending, msgid('Import BIND zone')) + button(pending, msgid('Export zone file')))}<div class="xp-whm-dns-file-fields">${field(pending, 'dns-import-file', msgid('BIND zone file'), { type: 'file' })}${field(pending, 'dns-import-text', msgid('BIND zone contents'), { type: 'textarea' })}</div>${table(v, msgid('Zone import differences'), [msgid('Name'), msgid('Type'), msgid('Current'), msgid('Imported'), msgid('Action')], [])}${actions(button(pending, msgid('Cancel')) + button(pending, msgid('Preview changes'), '', false, true))}${status(v, msgid('The existing zone editor remains connected to its DNS API. A BIND parser, difference review and zone-file serializer are not connected here; no file was imported or exported.'))}`)
    + card(v, 'dns-soa', msgid('SOA serial'), facts(v, [[msgid('Selected zone serial'), undefined], [msgid('Next serial'), undefined]]).replace('<dd>', '<dd data-whm-dns-soa-serial>') + status(v, msgid('The serial is shown only after an authorized zone read. Serial policy and the next value have not been read; this display never generates a serial.')))
    + card(v, 'dns-history', msgid('Zone change history'), table(v, msgid('Zone history'), [msgid('When (UTC)'), msgid(msgctxt('approved-xwhm', 'Actor')), msgid('Zone'), msgid('Change'), msgid('Serial'), msgid('Result')], []) + `<a class="xp-btn" href="/whm/audit?lang=${v.locale}">${v.text(msgid('Open audit log'))}</a>`)
    + card(v, 'dns-provider-health', msgid('PowerDNS API'), facts(v, [[msgid('Observed service'), checkedProvider?.name], [msgid('Service state'), checkedProvider ? v.text(checkedProvider.active ? msgid(msgctxt('approved-xwhm', 'Running')) : msgid('Stopped')) : undefined], [msgid('API connectivity'), undefined], [msgid('Last successful zone write'), undefined]]) + actions(button(pending, msgid('Check again'))) + status(v, msgid('A service observation is not proof of API connectivity or zone propagation. Provider health, pending writes and retry results have not been read.')))
}

/** Appended to the real DNS editor: no duplicate page heading or native mutation controls. */
export const renderWhmDnsSupplement = (input: DetailProps): string => {
  const principal = input.visibility?.principal ?? input.principal
  const acls = input.visibility?.reseller?.acl ?? input.activeReseller?.acl ?? []
  if (input.capabilityUnavailable || !(principal?.kind === 'root' || principal?.kind === 'reseller' && acls.includes('manage-dns'))) return ''
  const v: View = { props: input, locale: input.locale ?? 'en', readOnly: true, root: principal.kind === 'root', text: copy => escapeHtml(translator(input.locale)(copy)) }
  return `${styles}<section class="xp-whm-detail" data-approved-whm-dns-supplement>${dnsComponents(v)}</section>`
}

