export const whmDetailRoutes = Object.freeze(Object.keys(detailPages))

/** Full workspace structure survives unavailable host capabilities without exposing private records. */
export const renderWhmDetailPage = (input: DetailProps): string | undefined => {
  const route = input.activeRoute ?? '/whm'
  if (input.capabilityUnavailable && ['/whm/accounts', '/whm/accounts/new', '/whm/plans', '/whm/security/firewall', '/whm/services'].includes(route)) {
    const safe: DetailProps = { activeRoute: route, locale: input.locale, capabilityUnavailable: true }
    const v: View = { props: safe, locale: input.locale ?? 'en', readOnly: true, root: false, text: copy => escapeHtml(translator(input.locale)(copy)) }
    const accountList = card(v, 'account-list-unavailable', msgid('Accounts'), `<div class="xp-whm-detail-fields">${field(v, 'pending-account-search', msgid('Search accounts'))}${field(v, 'pending-account-owner', msgid('Owner'), { choices: [] })}${field(v, 'pending-account-plan', msgid('Plan'), { choices: [] })}${field(v, 'pending-account-status', msgid('Status'), { choices: [['active', msgid('Active')], ['suspended', msgid('Suspended')]] })}</div>${table(v, msgid('Accounts'), [msgid(msgctxt('approved-xwhm', 'Select')), msgid('Account'), msgid('Domain'), msgid('Owner'), 'IP', msgid('Plan'), msgid('Disk'), msgid(msgctxt('approved-xwhm', 'Bandwidth')), msgid('Status'), msgid('Actions')], [])}${actions(button(v, msgid('Previous')) + button(v, msgid('Next')))}`)
    const creation = card(v, 'account-create-unavailable', msgid('Account identity and plan'), `<div class="xp-whm-detail-fields">${field(v, 'username', msgid('Username'), { id: 'new-acc-username' })}${field(v, 'primaryDomain', msgid('Primary domain'), { id: 'new-acc-domain' })}${field(v, 'contactEmail', msgid('Contact email'), { id: 'new-acc-contact', type: 'email' })}${field(v, 'planId', msgid('Hosting plan'), { id: 'new-acc-plan', choices: [] })}${field(v, 'password', msgid('Password'), { id: 'new-acc-password', type: 'password' })}${field(v, 'ipAssignment', msgid('IPv4 assignment'), { id: 'new-acc-ipv4', choices: [] })}${field(v, 'ipv6', msgid('IPv6 address (optional)'), { id: 'new-acc-ipv6' })}</div>${renderApprovedWhmAccountCreateFields(safe)}${table(v, msgid('Selected plan capacity'), [msgid('Resource'), msgid('Plan'), msgid('After creation'), msgid('State')], [])}${actions(button(v, msgid('Create account'), '', true, true))}`)
    const planList = card(v, 'plans-unavailable', msgid('Hosting plans'), table(v, msgid('Hosting plans'), [msgid('Plan'), msgid('Disk / Bandwidth'), msgid('CPU / Memory'), msgid('Disk read / write'), msgid('Processes'), msgid('Addon domains'), msgid('Shell'), msgid('Actions')], []) + actions(button(v, msgid('Create plan'))))
    const planEditor = card(v, 'plan-editor-unavailable', msgid('Plan editor'), `<div class="xp-whm-detail-fields">${field(v, 'pending-plan-name', msgid('Plan name'))}${field(v, 'pending-plan-features', msgid('Feature list'), { choices: [] })}</div><h3>${v.text(msgid('Resources'))}</h3><div class="xp-whm-detail-fields">${PLAN_RESOURCE_FIELDS.map(item => field(v, `pending-plan-${item.key}`, item.label, { type: 'number' }) + choice(v, `pending-plan-unlimited-${item.key}`, msgid('Unlimited'), undefined)).join('')}</div><h3>${v.text(msgid('Service limits'))}</h3><div class="xp-whm-detail-fields">${PLAN_CAP_FIELDS.map(item => field(v, `pending-plan-${item.key}`, item.label, { type: 'number' }) + choice(v, `pending-plan-unlimited-${item.key}`, msgid('Unlimited'), undefined)).join('')}${field(v, 'pending-plan-mailbox-quota', PLAN_QUOTA_FIELD.label, { type: 'number' })}${field(v, 'pending-plan-shell', msgid('Shell access'), { choices: [['none', msgid('No shell')], ['jailed', msgid('Jailed shell')]] })}</div>${actions(button(v, msgid('Save plan'), '', true, true))}`)
    const services = card(v, 'managed-services-unavailable', msgid('Managed services'), table(v, msgid('Managed services'), [msgid('Service'), msgid('Unit'), msgid('Version'), msgid('State'), msgid('Memory'), msgid('Action')], []) + actions(button(v, msgid('Reload service')) + button(v, msgid('Restart service'))))
    const content = route === '/whm/accounts/new' ? creation + renderApprovedWhmAccountCreateStatus(safe)
      : route === '/whm/accounts' ? renderApprovedWhmAccountBulkControls(safe) + accountList
      : route === '/whm/plans' ? planList + planEditor + renderApprovedWhmPlanSupplement(safe)
      : route === '/whm/services' ? services + renderApprovedWhmOperationsSupplement(safe) : renderApprovedWhmOperationsSupplement(safe)
    const title = route === '/whm/accounts/new' ? msgid('Create account') : route === '/whm/accounts' ? msgid('Accounts') : route === '/whm/plans' ? msgid('Plans') : route === '/whm/services' ? msgid('Services') : msgid('Firewall')
    return workspace(v, route, title, msgid('Approved components remain visible while the host operation is unavailable.'), content)
  }
  if (input.capabilityUnavailable && route === '/whm/dns') {
    const v: View = { props: {}, locale: input.locale ?? 'en', readOnly: true, root: false, text: copy => escapeHtml(translator(input.locale)(copy)) }
    const editor = card(v, 'dns-editor-unavailable', msgid('Zones and records'), table(v, msgid('Zones'), [msgid('Zone'), msgid('Account'), msgid('Records'), msgid('Serial'), msgid('State')], []) + `<div class="xp-whm-detail-fields">${field(v, 'dns-pending-zone', msgid('Zone'), { choices: [] })}${field(v, 'dns-pending-account', msgid('Account'), { choices: [] })}${field(v, 'dns-pending-new-zone', msgid('New zone name'))}</div>${table(v, msgid('Records in the selected zone'), [msgid('Name'), msgid('Type'), 'TTL', msgid('Content'), msgid('Priority')], [])}${actions(button(v, msgid('Add zone')) + button(v, msgid('Edit records')) + button(v, msgid('Save zone')) + button(v, msgid('Delete zone')))}`)
    const record = card(v, 'dns-record-unavailable', msgid('Add a record'), `<div class="xp-whm-detail-fields">${field(v, 'dns-pending-record-type', msgid('Record type'), { choices: ['A', 'AAAA', 'CNAME', 'MX', 'TXT', 'SRV', 'CAA'].map(type => [type, type] as const) })}${field(v, 'dns-pending-record-name', msgid('Name'))}${field(v, 'dns-pending-record-ttl', 'TTL', { type: 'number' })}${field(v, 'dns-pending-record-content', msgid('Content'))}${field(v, 'dns-pending-record-priority', msgid('Priority'), { type: 'number' })}${field(v, 'dns-pending-record-weight', msgid('Weight'), { type: 'number' })}${field(v, 'dns-pending-record-port', msgid('Port'), { type: 'number' })}</div>${actions(button(v, msgid('Clear')) + button(v, msgid('Add record')))}`)
    return workspace(v, route, msgid('DNS zones'), msgid('Zone files, SOA, history and provider health remain visible until this host qualifies DNS operations.'), editor + record + dnsComponents(v))
  }
  if (input.capabilityUnavailable && ['/whm/backups', '/whm/backups/restore'].includes(route)) return renderApprovedWhmBackups({ activeRoute: route, locale: input.locale, capabilityUnavailable: true })
  if (input.capabilityUnavailable && ['/whm/resellers', '/whm/resellers/privileges'].includes(route)) return renderApprovedWhmResellers({ activeRoute: route, locale: input.locale, capabilityUnavailable: true })
  const page = detailPages[route]
  if (!page) return undefined
  const locale = input.locale ?? 'en'
  const text = (copy: Copy): string => escapeHtml(translator(locale)(copy))
  const principal = input.visibility?.principal ?? input.principal
  const acls = input.visibility?.reseller?.acl ?? input.activeReseller?.acl ?? []
  const authorized = principal?.kind === 'root' || (principal?.kind === 'reseller' && (route === '/whm/preferences' || (page.acl !== undefined && acls.includes(page.acl))))
  if (!input.capabilityUnavailable && !authorized) return `<section class="xp-card" data-whm-detail-denied role="status"><h1>${text(page.title)}</h1><p>${text(msgid('This workspace requires an authorized administrator context.'))}</p></section>`
  const operationId = route === '/whm/plans/features' ? 'feature-list-crud'
    : ['/whm/services/web', '/whm/security/ssh', '/whm/server/setup'].includes(route) ? 'server-settings-edit' : undefined
  const missingOperation = operationId !== undefined && !input.catalog?.some(tool => tool.id === operationId && tool.status === 'verified')
  const readOnly = input.capabilityUnavailable === true || missingOperation
  // A document availability fallback receives only route/locale. Ignore any accidental private DTOs.
  const props: DetailProps = readOnly ? { activeRoute: route, locale: input.locale, capabilityUnavailable: true } : input
  return page.render({ props, locale, readOnly, root: principal?.kind === 'root', text })
}


/** Exports contain only the authorized page and public labels, never internal audit keys or raw details. */
export const renderWhmAuditExports = (props: WhmSurfaceProps): string => {
  const locale = props.locale ?? 'en'
  const rows = (props.auditEntries ?? []).map(entry => ({
    at: entry.at,
    actor: auditActorLabel(entry.actor),
    action: auditActionLabel(entry.action, locale, entry),
    target: auditTargetLabel(entry.target, locale),
    outcome: auditOutcomeLabel(entry.action, entry.outcome, locale),
  }))
  const csvCell = (raw: string): string => {
    const safe = /^[=+@\-\t\r]/.test(raw) ? `'${raw}` : raw
    return `"${safe.replaceAll('"', '""')}"`
  }
  const csv = [['UTC', 'Actor', 'Action', 'Target', 'Outcome'], ...rows.map(row => [row.at, row.actor, row.action, row.target, row.outcome])].map(row => row.map(csvCell).join(',')).join('\r\n')
  const csvHref = `data:text/csv;charset=utf-8,${encodeURIComponent('\uFEFF' + csv).replaceAll("'", '%27')}`
  const jsonHref = `data:application/json;charset=utf-8,${encodeURIComponent(JSON.stringify(rows, null, 2)).replaceAll("'", '%27')}`
  return `<div class="xp-whm-detail-actions" data-audit-export><a class="xp-btn" download="xpanel-audit-page.csv" href="${escapeHtml(csvHref)}">${translator(locale)('Export page CSV')}</a><a class="xp-btn" download="xpanel-audit-page.json" href="${escapeHtml(jsonHref)}">${translator(locale)('Export page JSON')}</a></div>`
}

export const renderWhmAuditSupplement = (props: WhmSurfaceProps): string => {
  const v: View = { props, locale: props.locale ?? 'en', readOnly: true, root: true, text: copy => escapeHtml(translator(props.locale)(copy)) }
  const entries = props.auditEntries ?? []
  const detail = entries.map(entry => `<details data-audit-entry-detail><summary>${escapeHtml(auditActionLabel(entry.action, props.locale ?? 'en', entry))} · ${renderLtrValue(formatDisplayDateTime(entry.at))}</summary>${facts(v, [[msgid('Actor'), auditActorLabel(entry.actor)], [msgid('Target'), auditTargetLabel(entry.target, props.locale ?? 'en')], [msgid('Outcome'), auditOutcomeLabel(entry.action, entry.outcome, props.locale ?? 'en')]])}</details>`).join('')
  return `${styles}<div class="xp-whm-detail-grid" data-audit-supplement><div class="xp-whm-detail-column">${card(v, 'audit-recorded-entry', msgid('Recorded entry'), detail || status(v, msgid('No entries match the current page.')))}</div><aside class="xp-whm-detail-column">${card(v, 'audit-config-generations', msgid('Config generations'), generationTable(v))}<p class="xp-help">${v.text(msgid('Exports and details contain this authorized page only. Older entries use the keyset page links.'))}</p></aside></div>`
}
